window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a5e7babd4c9be5f4"]={"versions": [{"id": "FIG-a5e7babd4c9be5f4", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsverhaltens der AUTOSAR COM Kommunikationsschicht (AUTOSAR_SWS_COM). Dargestellt ist das Sendeverhalten einer I-PDU beim Umschalten des Transmission Mode (TMS-Switch) zwischen zwei periodischen Übertragungsmodi mit unterschiedlichen Zykluszeiten (Use Case A3: TM periodic + periodic).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse <code>t</code></strong>: Horizontale Achse zur Darstellung der zeitlichen Abfolge.\n</li><li><strong>I-PDU-Sendezeitpunkte</strong>: Vertikale Pfeile auf der Zeitachse:\n<ul class=\"fig-list\"><li>Grüne durchgezogene Pfeile: Tatsächliche zyklische Übertragungszeitpunkte der I-PDU.\n</li><li>Blauer gestrichelter Pfeil: Ursprünglich geplanter / unterdrückter Sendezeitpunkt der vorherigen Periode nach dem TMS-Wechsel.\n</li></ul>\n</li><li><strong>Modus-Zustände <code>v = a</code> und <code>v = b</code></strong>: Kennzeichnung des jeweils aktiven Transmission Mode (TM).\n</li><li><strong>TMS-Umschaltereignis</strong>: Rotes Blitz-Symbol oberhalb der Zeitachse zur Signalisierung des Umschaltzeitpunkts des Transmission Mode Selectors (TMS).\n</li><li><strong>Parameter &amp; Zeitintervalle</strong>:\n<ul class=\"fig-list\"><li><code>tc1</code>: Zykluszeit (Cycle Time) im Modus <code>a</code>.\n</li><li><code>tc2</code>: Zykluszeit (Cycle Time) im Modus <code>b</code>.\n</li><li><code>dt</code>: Sendeversatz / Deadline-Monitoring-Toleranz (Transmission Deadline / Delay Time).\n</li><li><code>tr, min</code>: Minimale Wiederholzeit bzw. Mindestabstand (Minimum Delay Time / Resubmission Time) zwischen zwei aufeinanderfolgenden Sendungen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Im Modus <code>v = a</code> wird die I-PDU periodisch mit der Zykluszeit <code>tc1</code> übertragen.\n</li><li>Ein TMS-Wechsel auf <code>v = b</code> wird durch ein Ereignis (Blitz-Symbol) ausgelöst.\n</li><li>Nach Ablauf des Mindestabstands <code>tr, min</code> startet die zyklische Übertragung im neuen Modus <code>v = b</code> mit der verkürzten Zykluszeit <code>tc2</code>.\n</li><li>Die I-PDU wird viermal mit dem Zyklusintervall <code>tc2</code> übertragen.\n</li><li>Ein erneuter TMS-Wechsel auf <code>v = a</code> tritt ein (zweites Blitz-Symbol).\n</li><li>Der zuvor im Modus <code>b</code> noch anstehende Zyklus-Sendezeitpunkt (blauer gestrichelter Pfeil) wird nicht mehr ausgeführt; stattdessen greift nach <code>tr, min</code> die neue Periode <code>tc1</code> für Modus <code>v = a</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Timing-Verhalten für den AUTOSAR COM Transmission Mode Selector (TMS) gemäß SWS COM:</p>\n<ul class=\"fig-list\"><li>Beim Umschalten zwischen zwei periodischen Übertragungsmodi (<code>PERIODIC</code>) mit unterschiedlichen Zykluszeiten (<code>ComTxModeTimePeriod</code>) muss das Senden im neuen Modus unverzüglich unter Einhaltung der minimalen Sendeabstandszeit <code>ComTxModeMinDelayTime</code> (<code>tr, min</code>) initiiert werden.\n</li><li>Laufende Zyklen des vorherigen Übertragungsmodus werden abgebrochen bzw. durch die neue Zykluszeit abgelöst.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f5ac7ccf723bbaac", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsverhaltens der AUTOSAR COM Kommunikationsschicht (AUTOSAR_SWS_COM). Dargestellt ist das Sendeverhalten einer I-PDU beim Umschalten des Transmission Mode (TMS-Switch) zwischen zwei periodischen Übertragungsmodi mit unterschiedlichen Zykluszeiten (Use Case A3: TM periodic + periodic).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse <code>t</code></strong>: Horizontale Achse zur Darstellung der zeitlichen Abfolge.\n</li><li><strong>I-PDU-Sendezeitpunkte</strong>: Vertikale Pfeile auf der Zeitachse:\n<ul class=\"fig-list\"><li>Grüne durchgezogene Pfeile: Tatsächliche zyklische Übertragungszeitpunkte der I-PDU.\n</li><li>Blauer gestrichelter Pfeil: Ursprünglich geplanter / unterdrückter Sendezeitpunkt der vorherigen Periode nach dem TMS-Wechsel.\n</li></ul>\n</li><li><strong>Modus-Zustände <code>v = a</code> und <code>v = b</code></strong>: Kennzeichnung des jeweils aktiven Transmission Mode (TM).\n</li><li><strong>TMS-Umschaltereignis</strong>: Rotes Blitz-Symbol oberhalb der Zeitachse zur Signalisierung des Umschaltzeitpunkts des Transmission Mode Selectors (TMS).\n</li><li><strong>Parameter &amp; Zeitintervalle</strong>:\n<ul class=\"fig-list\"><li><code>tc1</code>: Zykluszeit (Cycle Time) im Modus <code>a</code>.\n</li><li><code>tc2</code>: Zykluszeit (Cycle Time) im Modus <code>b</code>.\n</li><li><code>dt</code>: Sendeversatz / Deadline-Monitoring-Toleranz (Transmission Deadline / Delay Time).\n</li><li><code>tr, min</code>: Minimale Wiederholzeit bzw. Mindestabstand (Minimum Delay Time / Resubmission Time) zwischen zwei aufeinanderfolgenden Sendungen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Im Modus <code>v = a</code> wird die I-PDU periodisch mit der Zykluszeit <code>tc1</code> übertragen.\n</li><li>Ein TMS-Wechsel auf <code>v = b</code> wird durch ein Ereignis (Blitz-Symbol) ausgelöst.\n</li><li>Nach Ablauf des Mindestabstands <code>tr, min</code> startet die zyklische Übertragung im neuen Modus <code>v = b</code> mit der verkürzten Zykluszeit <code>tc2</code>.\n</li><li>Die I-PDU wird viermal mit dem Zyklusintervall <code>tc2</code> übertragen.\n</li><li>Ein erneuter TMS-Wechsel auf <code>v = a</code> tritt ein (zweites Blitz-Symbol).\n</li><li>Der zuvor im Modus <code>b</code> noch anstehende Zyklus-Sendezeitpunkt (blauer gestrichelter Pfeil) wird nicht mehr ausgeführt; stattdessen greift nach <code>tr, min</code> die neue Periode <code>tc1</code> für Modus <code>v = a</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Timing-Verhalten für den AUTOSAR COM Transmission Mode Selector (TMS) gemäß SWS COM:</p>\n<ul class=\"fig-list\"><li>Beim Umschalten zwischen zwei periodischen Übertragungsmodi (<code>PERIODIC</code>) mit unterschiedlichen Zykluszeiten (<code>ComTxModeTimePeriod</code>) muss das Senden im neuen Modus unverzüglich unter Einhaltung der minimalen Sendeabstandszeit <code>ComTxModeMinDelayTime</code> (<code>tr, min</code>) initiiert werden.\n</li><li>Laufende Zyklen des vorherigen Übertragungsmodus werden abgebrochen bzw. durch die neue Zykluszeit abgelöst.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a5e7babd4c9be5f4", "to": "FIG-f5ac7ccf723bbaac", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Blitz-Symbole zur Kennzeichnung des TMS-Umschaltereignisses (v = b bzw. v = a): Darstellung von roter Vollton-Füllung auf feine rote Konturlinie ohne Füllung geändert.\n</li><li>Textbeschriftungen und Bemaßungen: Neuplatzierung / Neu-Rendering einzelner Textelemente (unter anderem <code>dt</code> und <code>tr, min</code>).\n</li></ul>"}]};
